<!-- Quizzy design: "Moderator / Question form" frame, exported from the design file. Static: nothing on this page is interactive. -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Quizzy · Question form</title>
<link rel="stylesheet" href="quizzy.css">
</head>
<body>
  <!-- Layer: Header -->
  <header class="admin-header">
    <span class="logo"><span class="logo__mark">?</span>Quizzy</span>
    <span class="admin-header__tag">Moderator</span>
  </header>

  <main class="admin-main">
    <div class="breadcrumbs"><a href="#">← Frontend Fest 2026</a></div>
    <div class="page-head"><h1>New question</h1></div>

    <!-- Layer: Form card -->
    <div class="card">
      <div class="field">
        <span class="field-label">Question</span>
        <textarea class="input" rows="3">Which planet is the largest?</textarea>
      </div>

      <div class="field">
        <span class="field-label">Options</span>
        <span class="field-hint">Mark the correct options, at least one. Empty rows are skipped.</span>
      </div>

      <!-- Component: Option row (text, correct switch, remove) -->
      <div class="option-rows">
        <div class="option-row"><input class="input" type="text" value="Jupiter"><span class="checkbox"><input type="checkbox" checked> Correct</span><span class="btn btn--danger btn--icon">✕</span></div>
        <div class="option-row"><input class="input" type="text" value="Saturn"><span class="checkbox"><input type="checkbox"> Correct</span><span class="btn btn--danger btn--icon">✕</span></div>
        <div class="option-row"><input class="input" type="text" value="Earth"><span class="checkbox"><input type="checkbox"> Correct</span><span class="btn btn--danger btn--icon">✕</span></div>
        <div class="option-row"><input class="input" type="text" placeholder="Option text"><span class="checkbox"><input type="checkbox"> Correct</span><span class="btn btn--danger btn--icon">✕</span></div>
      </div>
      <div class="buttons" style="margin-bottom: 28px"><span class="btn btn--ghost btn--sm">+ Add option</span></div>

      <div class="field">
        <span class="checkbox"><input type="checkbox" checked> Active</span>
        <span class="field-hint">Only active questions are played.</span>
      </div>

      <!-- Layer: Error state (shown when a rule fails) -->
      <div class="errors">Mark at least one option as correct</div>

      <div class="buttons">
        <span class="btn btn--pink">Save question</span>
        <span class="btn btn--ghost">Cancel</span>
      </div>
    </div>
  </main>
</body>
</html>
/*
 * Quizzy: a live quiz for conference screens.
 * Bright colors for LED walls and projectors, big type, pill buttons.
 */

@font-face {
  font-family: "Inter";
  font-display: swap;
  font-style: normal;
  font-weight: 100 900;
  src: url("Inter-latin.woff2") format("woff2");
}

:root {
  --c-lavender: #e9e6ff;
  --c-blue: #2a12c9;
  --c-pink: #ff2e88;
  --c-night: #0d0640;
  --c-sun: #ffd23f;
  --c-white: #fff;
  --c-success: #00b36b;
  --c-muted: #6f66b8;

  --f-display: "Inter", system-ui, sans-serif;
  --f-text: "Inter", system-ui, -apple-system, sans-serif;

  --radius: 16px;
  --gutter: clamp(16px, 4vw, 60px);
}

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  min-height: 100vh;
  min-height: 100dvh;
  background: var(--c-lavender);
  color: var(--c-blue);
  font-family: var(--f-text);
  font-size: 18px;
  line-height: 1.35;
  letter-spacing: -0.01em;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3 {
  font-family: var(--f-display);
  font-weight: 900;
  letter-spacing: -0.035em;
  line-height: 1;
  margin: 0 0 0.5em;
}

h1 { font-size: clamp(36px, 6vw, 72px); }
h2 { font-size: clamp(26px, 3.5vw, 44px); }
h3 { font-size: clamp(20px, 2.2vw, 28px); }

p { margin: 0 0 1em; }

a { color: inherit; text-underline-offset: 0.15em; }
a:hover { color: var(--c-pink); }

img, svg { max-width: 100%; }

.logo {
  display: inline-flex;
  align-items: center;
  gap: 0.18em;
  font: 900 32px/1 var(--f-display);
  letter-spacing: -0.05em;
  color: inherit;
  white-space: nowrap;
}
.logo__mark {
  display: inline-grid;
  place-items: center;
  width: 1.05em;
  height: 1.05em;
  border-radius: 50% 50% 50% 12%;
  background: var(--c-sun);
  color: var(--c-night);
  font-size: 0.8em;
  letter-spacing: 0;
}

/* ---------- Buttons ---------- */

.btn {
  appearance: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4em;
  border: 0;
  border-radius: 1000px;
  background: var(--c-blue);
  color: var(--c-lavender);
  font: 600 18px/1 var(--f-text);
  letter-spacing: -0.01em;
  padding: 0.85em 1.4em;
  text-decoration: none;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color 0.15s, color 0.15s, box-shadow 0.15s;
}

.btn:hover {
  background: var(--c-lavender);
  color: var(--c-",
  "output_tail": "--c-pink); color: var(--c-white); }
.badge--finished { background: var(--c-blue); color: var(--c-lavender); }

.preview-banner {
  background: var(--c-blue);
  color: var(--c-lavender);
  padding: 10px var(--gutter);
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  font-weight: 600;
  font-size: 15px;
}
.preview-banner a { color: var(--c-lavender); }

/* ---------- Hero / cover decor ---------- */

.cover {
  position: relative;
  overflow: hidden;
  background: var(--c-pink);
  color: var(--c-white);
  isolation: isolate;
}

.cover--blue { background: var(--c-blue); }
.cover--night { background: var(--c-night); }

/* Two floating blobs: a sun-yellow circle and a soft ring */
.cover::before, .cover::after {
  content: "";
  position: absolute;
  z-index: -1;
  pointer-events: none;
  border-radius: 50%;
}

.cover::before {
  width: 70vmax;
  height: 70vmax;
  right: -28vmax;
  top: -30vmax;
  background: var(--c-sun);
  opacity: 0.9;
  animation: blob-move 6s ease-in-out infinite alternate;
}

.cover::after {
  width: 60vmax;
  height: 60vmax;
  left: -24vmax;
  bottom: -34vmax;
  border: 9vmax solid rgb(255 255 255 / 0.16);
  animation: blob-move 9s ease-in-out infinite alternate-reverse;
}

.cover--blue::before { background: var(--c-pink); }
.cover--night::before { background: var(--c-blue); }
.cover--calm::before, .cover--calm::after { opacity: 0.3; }

@keyframes blob-move { to { transform: translate(-3vmax, 2vmax) scale(1.04); } }

@media (prefers-reduced-motion: reduce) {
  .cover::before, .cover::after { animation: none; }
}

/* ---------- Big screen (moderator presentation) ---------- */

.screen {
  min-height: 100vh;
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  padding: clamp(20px, 3vw, 56px);
  padding-bottom: 110px;
}

.screen__top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(18px, 1.8vw, 30px);
}

.screen__logo { font-size: clamp(28px, 3vw, 52px); }

.screen__body { flex: 1; display: flex; flex-direction: column; justify-content: center; }

.screen-controls {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 50;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 16px clamp(20px, 3vw, 56px);
  padding-bottom: calc(16px + env(safe-area-inset-bottom, 0px));
  background: rgb(0 0 51 / 0.85);
  backdrop-filter: blur(8px);
  color: var(--c-lavender);
  font-size: 16px;
}
.screen-controls a { color: var(--c-lavender); }
.screen-controls__info { display: flex; gap: 24px; align-items: center; flex-wrap: wrap; }

/* Lobby */

.lobby { display: grid; grid-template-columns: 1fr auto; gap: clamp(24px, 4vw, 80px); align-items: center; }

.lobby__title {
  font-size: clamp(48px, 7vw, 140px);
  line-height: 0.9;
  margin-bottom: 0.3em;
  overflow-wrap: anywhere;
}

.lobby__join { font-size: clamp(20px, 2.2vw, 40px); font-weight: 600; margin-bottom: 0.3em; }
.lobby__url { font-family: var(--f-display); font-weight: 800; font-size: clamp(28px, 3.6vw, 72px); line-height: 1; overflow-wrap: anywhere; }

.qr {
  background: var(--c-white);
  border-radius: clamp(16px, 2vw, 32px);
  padding: clamp(12px, 1.4vw, 28px);
  width: min(62vh, 42vw);
  aspect-ratio: 1;
  box-shadow: 0 30px 80px rgb(0 0 51 / 0.35);
}
.qr svg { width: 100%; height: 100%; display: block; }

.counter-pill {
  display: inline-flex;
  align-items: baseline;
  gap: 0.4em;
  margin-top: 1.2em;
  padding: 0.4em 0.9em;
  border-radius: 1000px;
  background: rgb(221 221 255 / 0.18);
  font-size: clamp(18px, 1.8vw, 30px);
  font-weight: 600;
}
.counter-pill strong { font-family: var(--f-display); font-weight: 900; font-size: 1.3em; }

@media (max-width: 800px) {
  .lobby { grid-template-columns: 1fr; }
  .qr { width: min(80vw, 420px); }
}

/* Question on the big screen */

.stage-question__num { font-family: var(--f-display); font-weight: 800; font-size: clamp(20px, 2vw, 36px); opacity: 0.8; margin-bottom: 0.6em; }

.stage-question__body {
  font-family: var(--f-display);
  font-weight: 800;
  font-size: clamp(32px, 4.4vw, 88px);
  line-height: 1.02;
  letter-spacing: -0.02em;
  margin-bottom: clamp(24px, 3vw, 56px);
  white-space: pre-line;
  overflow-wrap: anywhere;
}

.stage-options {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 420px), 1fr));
  gap: clamp(12px, 1.4vw, 24px);
}

.stage-option {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.8em;
  overflow: hidden;
  background: var(--c-lavender);
  color: var(--c-blue);
  border-radius: clamp(14px, 1.4vw, 24px);
  padding: 0.8em 1em;
  font-size: clamp(20px, 2.2vw, 40px);
  font-weight: 600;
  line-height: 1.15;
  isolation: isolate;
  transition: opacity 0.3s, transform 0.3s;
}

