    if quizzes.is_empty() {
        html.push_str(r#"<div class="empty"><h3>Your next great quiz starts here</h3><p>Create a quiz, then add questions for your audience.</p></div>"#);
    } else {
        html.push_str(r#"<ul class="quiz-list">"#);
