mod db;
mod views;

use axum::{
    Router, Form,
    extract::{Path, State, Request},
    http::{StatusCode, header},
    middleware::{self, Next},
    response::{Html, IntoResponse, Redirect, Response},
    routing::{get, post},
};
use base64::{Engine, engine::general_purpose::{STANDARD, URL_SAFE_NO_PAD}};
use hmac::{Hmac, Mac};
use rusqlite::{Connection, params};
use sha2::Sha256;
use std::{collections::HashMap, sync::{Arc, Mutex, MutexGuard}};
use db::{OptionRow, Question};

type HmacSha256 = Hmac<Sha256>;
type AppState = Arc<App>;
type Fields = HashMap<String, String>;
type Result<T> = std::result::Result<T, AppError>;

struct App {
    db: Mutex<Connection>,
    secret: String,
    credential_signature: Vec<u8>,
    csrf: String,
}

impl App {
    fn db(&self) -> Result<MutexGuard<'_, Connection>> {
        self.db.lock().map_err(|_| AppError::Internal("Database lock poisoned".into()))
    }
    fn check_csrf(&self, fields: &Fields) -> Result<()> {
        let token = URL_SAFE_NO_PAD.decode(field(fields, "csrf")).map_err(|_| AppError::Forbidden)?;
        let mut mac = HmacSha256::new_from_slice(self.secret.as_bytes()).unwrap();
        mac.update(b"quizzy moderator csrf v1");
        mac.verify_slice(&token).map_err(|_| AppError::Forbidden)
    }
}

#[derive(Debug)]
enum AppError { NotFound, Forbidden, BadRequest, Internal(String) }
impl From<rusqlite::Error> for AppError {
    fn from(error: rusqlite::Error) -> Self { Self::Internal(error.to_string()) }
}
impl IntoResponse for AppError {
    fn into_response(self) -> Response {
        let (status, message) = match self {
            Self::NotFound => (StatusCode::NOT_FOUND, "Page not found"),
            Self::Forbidden => (StatusCode::FORBIDDEN, "Invalid form token. Reload the page and try again."),
            Self::BadRequest => (StatusCode::BAD_REQUEST, "Invalid request"),
            Self::Internal(error) => { eprintln!("Application error: {error}"); (StatusCode::INTERNAL_SERVER_ERROR, "Something went wrong. Please try again.") }
        };
        (status, Html(views::page(message, &format!("<h2>{message}</h2><a href=\"/moderate\">All quizzes</a>")))).into_response()
    }
}

fn signature(secret: &str, message: &[u8]) -> Vec<u8> {
    let mut mac = HmacSha256::new_from_slice(secret.as_bytes()).unwrap();
    mac.update(message);
    mac.finalize().into_bytes().to_vec()
}

async fn protect(State(app): State<AppState>, request: Request, next: Next) -> Response {
    let path = request.uri().path();
    let moderator = path == "/moderate" || path.starts_with("/moderate/");
    if moderator {
        let authorized = request.headers().get(header::AUTHORIZATION).and_then(|h| h.to_str().ok())
            .and_then(|h| h.split_once(' ')).filter(|(scheme, _)| scheme.eq_ignore_ascii_case("Basic"))
            .and_then(|(_, credentials)| STANDARD.decode(credentials).ok())
            .is_some_and(|credentials| {
                let mut mac = HmacSha256::new_from_slice(app.secret.as_bytes()).unwrap();
                mac.update(&credentials);
                mac.verify_slice(&app.credential_signature).is_ok()
            });
        if !authorized {
            return (StatusCode::UNAUTHORIZED, [
                (header::WWW_AUTHENTICATE, "Basic realm=\"Quizzy Moderator\", charset=\"UTF-8\""),
                (header::CACHE_CONTROL, "no-store"),
            ], "Moderator authentication required").into_response();
        }
    }
    let mut response = next.run(request).await;
    let headers = response.headers_mut();
    headers.insert(header::X_CONTENT_TYPE_OPTIONS, "nosniff".parse().unwrap());
    headers.insert(header::CONTENT_SECURITY_POLICY, "default-src 'self'; script-src 'self'; style-src 'self'; font-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'".parse().unwrap());
    headers.insert(header::REFERRER_POLICY, "same-origin".parse().unwrap());
    if moderator {
        headers.insert(header::CACHE_CONTROL, "no-store".parse().unwrap());
        headers.insert(header::VARY, "Authorization".parse().unwrap());
    }
    response
}

fn field<'a>(fields: &'a Fields, key: &str) -> &'a str { fields.get(key).map(String::as_str).unwrap_or("") }
fn quiz_title(db: &Connection, id: i64) -> Result<String> { db::title(db, id)?.ok_or(AppError::NotFound) }
fn find_question(db: &Connection, quiz_id: i64, id: i64) -> Result<Question> {
    db::questions(db, quiz_id)?.into_iter().find(|q| q.id == id).ok_or(AppError::NotFound)
}
fn go_to_quiz(id: i64) -> Response { Redirect::to(&format!("/moderate/quizzes/{id}")).into_response() }

async fn up(State(app): State<AppState>) -> Result<&'static str> {
    app.db()?.query_row("SELECT 1", [], |_| Ok(()))?;
    Ok("OK")
}

async fn quizzes(State(app): State<AppState>) -> Result<Html<String>> {
    let db = app.db()?;
    let mut stmt = db.prepare("SELECT q.id, q.title, COUNT(s.id), COALESCE(SUM(s.active), 0) FROM quizzes q LEFT JOIN questions s ON s.quiz_id = q.id GROUP BY q.id ORDER BY q.id DESC")?;
    let quizzes = stmt.query_map([], |r| Ok((r.get(0)?, r.get(1)?, r.get(2)?, r.get(3)?)))?.collect::<rusqlite::Result<Vec<_>>>()?;
    Ok(Html(views::quiz_list(&quizzes)))
}
async fn new_quiz(State(app): State<AppState>) -> Html<String> { Html(views::quiz_form(None, "", &app.csrf, &[])) }
async fn edit_quiz(State(app): State<AppState>, Path(id): Path<i64>) -> Result<Html<String>> {
    let title = quiz_title(&app.db()?, id)?;
    Ok(Html(views::quiz_form(Some(id), &title, &app.csrf, &[])))
}
async fn show_quiz(State(app): State<AppState>, Path(id): Path<i64>) -> Result<Html<String>> {
    let db = app.db()?;
    Ok(Html(views::quiz(id, &quiz_title(&db, id)?, &db::questions(&db, id)?, &app.csrf)))
}
async fn create_quiz(State(app): State<AppState>, Form(fields): Form<Fields>) -> Result<Response> {
    save_quiz(&app, None, &fields)
}
async fn update_quiz(State(app): State<AppState>, Path(id): Path<i64>, Form(fields): Form<Fields>) -> Result<Response> {
    save_quiz(&app, Some(id), &fields)
}
fn save_quiz(app: &App, id: Option<i64>, fields: &Fields) -> Result<Response> {
    app.check_csrf(fields)?;
    let db = app.db()?;
    if let Some(id) = id { quiz_title(&db, id)?; }
    let title = field(fields, "title");
    if title.trim().is_empty() {
        return Ok((StatusCode::UNPROCESSABLE_ENTITY, Html(views::quiz_form(id, title, &app.csrf, &["Title is required"]))).into_response());
    }
    let id = match id {
        Some(id) => { db.execute("UPDATE quizzes SET title = ? WHERE id = ?", params![title.trim(), id])?; id }
        None => { db.execute("INSERT INTO quizzes(title) VALUES (?)", [title.trim()])?; db.last_insert_rowid() }
    };
    Ok(go_to_quiz(id))
}
async fn delete_quiz(State(app): State<AppState>, Path(id): Path<i64>, Form(fields): Form<Fields>) -> Result<Redirect> {
    app.check_csrf(&fields)?;
    let db = app.db()?;
    quiz_title(&db, id)?;
    db.execute("DELETE FROM quizzes WHERE id = ?", [id])?;
    Ok(Redirect::to("/moderate"))
}
async fn new_question(State(app): State<AppState>, Path(quiz_id): Path<i64>) -> Result<Html<String>> {
    let title = quiz_title(&app.db()?, quiz_id)?;
    let q = Question { id: 0, text: String::new(), active: true, options: vec![OptionRow { text: String::new(), correct: false }; 4] };
    Ok(Html(views::question_form(quiz_id, &title, &q, &app.csrf, &[])))
}
async fn edit_question(State(app): State<AppState>, Path((quiz_id, id)): Path<(i64, i64)>) -> Result<Html<String>> {
    let db = app.db()?;
    let title = quiz_title(&db, quiz_id)?;
    let q = find_question(&db, quiz_id, id)?;
    Ok(Html(views::question_form(quiz_id, &title, &q, &app.csrf, &[])))
}
fn parse_question(id: i64, fields: &Fields) -> Question {
    let mut numbers: Vec<usize> = fields.keys().filter_map(|key| key.strip_prefix("option_")?.parse().ok()).collect();
    numbers.sort_unstable();
    let options = numbers.into_iter().map(|n| OptionRow {
        text: field(fields, &format!("option_{n}")).into(),
        correct: field(fields, &format!("correct_{n}")) == "1",
    }).collect();
    Question { id, text: field(fields, "question").into(), active: field(fields, "active") == "1", options }
}
fn validate_question(q: &Question) -> Vec<&'static str> {
    let mut messages = vec![];
    if q.text.trim().is_empty() { messages.push("Question is required"); }
    let options: Vec<_> = q.options.iter().filter(|o| !o.text.trim().is_empty()).collect();
    if options.len() < 2 { messages.push("Add at least two options"); }
    if !options.iter().any(|o| o.correct) { messages.push("Mark at least one option as correct"); }
    messages
}
async fn create_question(State(app): State<AppState>, Path(quiz_id): Path<i64>, Form(fields): Form<Fields>) -> Result<Response> {
    save_question(&app, quiz_id, 0, &fields)
}
async fn update_question(State(app): State<AppState>, Path((quiz_id, id)): Path<(i64, i64)>, Form(fields): Form<Fields>) -> Result<Response> {
    if id <= 0 { return Err(AppError::NotFound); }
    save_question(&app, quiz_id, id, &fields)
}
fn save_question(app: &App, quiz_id: i64, id: i64, fields: &Fields) -> Result<Response> {
    app.check_csrf(fields)?;
    let mut db = app.db()?;
    let title = quiz_title(&db, quiz_id)?;
    if id != 0 { find_question(&db, quiz_id, id)?; }
    let q = parse_question(id, fields);
    let messages = validate_question(&q);
    if !messages.is_empty() {
        return Ok((StatusCode::UNPROCESSABLE_ENTITY, Html(views::question_form(quiz_id, &title, &q, &app.csrf, &messages))).into_response());
    }
    let options: Vec<_> = q.options.into_iter().filter(|o| !o.text.trim().is_empty()).map(|o| OptionRow { text: o.text.trim().into(), correct: o.correct }).collect();
    let tx = db.transaction()?;
    let question_id = if id == 0 {
        tx.execute("INSERT INTO questions(quiz_id, text, active, position) VALUES (?, ?, ?, (SELECT COALESCE(MAX(position), -1) + 1 FROM questions WHERE quiz_id = ?))", params![quiz_id, q.text.trim(), q.active, quiz_id])?;
        tx.last_insert_rowid()
    } else {
        tx.execute("UPDATE questions SET text = ?, active = ? WHERE id = ? AND quiz_id = ?", params![q.text.trim(), q.active, id, quiz_id])?;
        id
    };
    db::write_options(&tx, question_id, &options)?;
    tx.commit()?;
    Ok(go_to_quiz(quiz_id))
}
async fn active_question(State(app): State<AppState>, Path((quiz_id, id)): Path<(i64, i64)>, Form(fields): Form<Fields>) -> Result<Response> {
    app.check_csrf(&fields)?;
    let db = app.db()?;
    find_question(&db, quiz_id, id)?;
    db.execute("UPDATE questions SET active = ? WHERE id = ? AND quiz_id = ?", params![field(&fields, "active") == "1", id, quiz_id])?;
    Ok(go_to_quiz(quiz_id))
}
async fn delete_question(State(app): State<AppState>, Path((quiz_id, id)): Path<(i64, i64)>, Form(fields): Form<Fields>) -> Result<Response> {
    app.check_csrf(&fields)?;
    let mut db = app.db()?;
    find_question(&db, quiz_id, id)?;
    let tx = db.transaction()?;
    tx.execute("DELETE FROM questions WHERE id = ? AND quiz_id = ?", params![id, quiz_id])?;
    let ids: Vec<_> = db::questions(&tx, quiz_id)?.iter().map(|q| q.id).collect();
    db::resequence(&tx, quiz_id, &ids)?;
    tx.commit()?;
    Ok(go_to_quiz(quiz_id))
}
async fn move_question(State(app): State<AppState>, Path((quiz_id, id)): Path<(i64, i64)>, Form(fields): Form<Fields>) -> Result<Response> {
    app.check_csrf(&fields)?;
    let mut db = app.db()?;
    let tx = db.transaction()?;
    let mut ids: Vec<_> = db::questions(&tx, quiz_id)?.iter().map(|q| q.id).collect();
    let index = ids.iter().position(|q| *q == id).ok_or(AppError::NotFound)?;
    let other = match field(&fields, "direction") {
        "up" => index.saturating_sub(1),
        "down" => (index + 1).min(ids.len() - 1),
        _ => return Err(AppError::BadRequest),
    };
    ids.swap(index, other);
    db::resequence(&tx, quiz_id, &ids)?;
    tx.commit()?;
    Ok(go_to_quiz(quiz_id))
}
async fn preview(State(app): State<AppState>, Path(id): Path<i64>) -> Result<Html<String>> {
    let db = app.db()?;
    Ok(Html(views::preview(id, &quiz_title(&db, id)?, &db::questions(&db, id)?)))
}
async fn asset(Path(name): Path<String>) -> Response {
    let (mime, data): (&str, &[u8]) = match name.as_str() {
        "quizzy.css" => ("text/css; charset=utf-8", include_bytes!("../assets/quizzy.css")),
        "app.css" => ("text/css; charset=utf-8", include_bytes!("../assets/app.css")),
        "app.js" => ("application/javascript; charset=utf-8", include_bytes!("../assets/app.js")),
        "Inter-latin.woff2" => ("font/woff2", include_bytes!("../assets/Inter-latin.woff2")),
        _ => return StatusCode::NOT_FOUND.into_response(),
    };
    ([(header::CONTENT_TYPE, mime), (header::CACHE_CONTROL, "public, max-age=3600")], data).into_response()
}

async fn shutdown() {
    let ctrl_c = async { tokio::signal::ctrl_c().await.expect("Cannot listen for Ctrl-C"); };
    #[cfg(unix)]
    let terminate = async { tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate()).expect("Cannot listen for SIGTERM").recv().await; };
    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();
    tokio::select! { _ = ctrl_c => {}, _ = terminate => {} }
}

#[tokio::main]
async fn main() -> std::result::Result<(), Box<dyn std::error::Error>> {
    let required = |name: &str| -> std::result::Result<String, Box<dyn std::error::Error>> {
        let value = std::env::var(name).map_err(|_| format!("Set {name}"))?;
        if value.is_empty() { return Err(format!("{name} must not be empty").into()); }
        Ok(value)
    };
    let secret = required("SECRET_KEY_BASE")?;
    let credentials = format!("{}:{}", required("QUIZZY_MODERATOR_USERNAME")?, required("QUIZZY_MODERATOR_PASSWORD")?);
    std::fs::create_dir_all("storage")?;
    let db = Connection::open("storage/quizzy.sqlite3")?;
    db::initialize(&db)?;
    let app = Arc::new(App { db: Mutex::new(db), credential_signature: signature(&secret, credentials.as_bytes()), csrf: URL_SAFE_NO_PAD.encode(signature(&secret, b"quizzy moderator csrf v1")), secret });
    let router = Router::new()
        .route("/", get(|| async { Redirect::to("/moderate") }))
        .route("/up", get(up))
        .route("/assets/{name}", get(asset))
        .route("/moderate", get(quizzes))
        .route("/moderate/", get(quizzes))
        .route("/moderate/quizzes/new", get(new_quiz))
        .route("/moderate/quizzes", post(create_quiz))
        .route("/moderate/quizzes/{id}", get(show_quiz).post(update_quiz))
        .route("/moderate/quizzes/{id}/edit", get(edit_quiz))
        .route("/moderate/quizzes/{id}/delete", post(delete_quiz))
        .route("/moderate/quizzes/{id}/preview", get(preview))
        .route("/moderate/quizzes/{quiz_id}/questions/new", get(new_question))
        .route("/moderate/quizzes/{quiz_id}/questions", post(create_question))
        .route("/moderate/quizzes/{quiz_id}/questions/{id}", post(update_question))
        .route("/moderate/quizzes/{quiz_id}/questions/{id}/edit", get(edit_question))
        .route("/moderate/quizzes/{quiz_id}/questions/{id}/delete", post(delete_question))
        .route("/moderate/quizzes/{quiz_id}/questions/{id}/active", post(active_question))
        .route("/moderate/quizzes/{quiz_id}/questions/{id}/move", post(move_question))
        .fallback(|| async { AppError::NotFound })
        .layer(middleware::from_fn_with_state(app.clone(), protect))
        .with_state(app);
    let port: u16 = std::env::var("PORT").unwrap_or("3000".into()).parse()?;
    let listener = tokio::net::TcpListener::bind((std::net::Ipv4Addr::UNSPECIFIED, port)).await?;
    println!("Quizzy is ready on http://0.0.0.0:{port}");
    axum::serve(listener, router).with_graceful_shutdown(shutdown()).await?;
    Ok(())
}

